  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.drmtlgy.com/pages/affiliate-login', 'official_site', 'affiliate', 'DRMTLGY''s own affiliate program page states ''15% Commission on Every Sale'' and, in the same commission benefit, ''Earn unlimited commissions by sharing your personalized link'' — an explicit no-earnings-cap statement on the brand''s own program page, so the cap is recorded UNCAPPED. The page also promises performance-based bonuses, milestone gifting and a $55+ average order value.', 'verified', now());
