  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'OSEA Seaweed Society Affiliate Program (16% base, tiers to 20%, via Refersion)', 'https://oseamalibu.refersion.com', 'https://oseamalibu.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://oseamalibu.com/pages/affiliates', 'official_site', 'affiliate', 'OSEA''s own affiliates page publishes its tier table: Basic pays 16% commission ($0–$500/month revenue), Gold 18% ($500+/month) and Platinum 20% ($2,500+/month), with a 2x-month posting requirement and a $278 welcome product package. Applications run through Refersion (oseamalibu.refersion.com); the page suggests 4,000+ followers but invites smaller creators to apply.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://oseamalibu.com/pages/affiliates', 'official_site', 'contact', 'The brand publishes affiliates@oseamalibu.com on its own affiliates page for affiliate support and discount-code help.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://oseamalibu.com/pages/partnerships', 'official_site', 'ugc_collab', 'OSEA''s partnerships page lists four creator routes: the Seaweed Society affiliate program (up to 20% commission), paid brand partnerships, a creator gifting program and a UGC creator program; its content guidelines require #OSEAPartner tagging and honest reviews.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/101463', 'affiliate_network', 'compensation', 'OSEA''s Awin merchant profile lists a 1–16% commission range ''based on publisher type'' with a 30-day cookie — a publisher-network range that sits below the brand''s own published creator tiers (16% base), so the brand''s own tier table governs the recorded rate.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 18, 14, 9, 4, '{"niche_fit": "Clean seaweed skincare for face and body is a core skincare-UGC category, with texture demos and before/after content the brand itself coaches affiliates to make.", "ugc_evidence": "Four published creator routes on the brand''s own partnerships page \u2014 affiliate, paid partnerships, gifting and a UGC program \u2014 with detailed content guidelines for partners.", "compensation": "Published tiered cash commission on the brand''s own page: 16% base rising to 18% and 20% on monthly revenue, plus a $278 welcome package and monthly gifting at higher tiers.", "contact_access": "A dedicated affiliate email (affiliates@oseamalibu.com) is published on the program page, plus an open Refersion application.", "opportunity_availability": "Applications are open on the brand''s own page; the 4,000-follower guideline is explicitly not a hard floor.", "credibility": "Long-established clean-beauty brand with a physical spa presence and fully published program terms on its own store."}'::jsonb);
