  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lashify Creators (15% starting commission, tiers to 20%)', 'https://www.lashify.com/apps/lashify/creators', 'https://www.lashify.com/apps/lashify/creators', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lashify.com/apps/lashify/creators', 'official_site', 'affiliate', 'Lashify''s own Creators page publishes its tiers: everyone starts at 15% on every order through their link or code, rising to 18% (Partner, $1,500 in sales in the last 90 days) and 20% (Icon, $5,000 in the last 90 days). Earnings are paid monthly on the 15th by PayPal (or LashCash store credit with 25% extra). Joining requires at least 10,000 followers on one platform.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lashify.com/apps/lashify/creators', 'official_site', 'contact', 'The Creators page publishes partners@lashify.com for makeup-artist invitations and for former Affiliate Alliance members migrating to Lashify Creators.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lashify.com/apps/lashify/creators', 'official_site', 'ugc_collab', 'The program is built around creator content: members get lessons on the system and techniques, ready-to-post captions and products to film, and their followers get 2 free lashes on a first order of $100 or more.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 17, 11, 7, 4, '{"niche_fit": "DIY lash application is one of the most demo-driven beauty categories on TikTok \u2014 the product only makes sense in video.", "ugc_evidence": "The brand''s own Creators program supplies lessons, captions and products to film, and replaced its older Affiliate Alliance \u2014 a deliberate creator-first rebuild.", "compensation": "Published cash commission on the brand''s own page \u2014 15% starting, 18% and 20% performance tiers \u2014 paid monthly via PayPal.", "contact_access": "A published partner email (partners@lashify.com) plus an on-site application; the email route is aimed at makeup artists and migrating affiliates.", "opportunity_availability": "Open application, but gated: creators need at least 10,000 followers on one platform (makeup artists by invitation).", "credibility": "Category-defining lash brand with fully published rates, payout timing and level rules on its own site."}'::jsonb);
