  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 15, 8, 9, 4, '{"niche_fit": "Hair-growth and styling-tool content is a proven hair-UGC category built on routine and progress videos.", "ugc_evidence": "The brand''s own collabs page is creator-facing: a posting rhythm (2x/month), monthly prizes and restocks for active affiliates.", "compensation": "Published cash commission on the brand''s own page \u2014 12% base rising to 15% after 60 days with strong engagement \u2014 paid monthly.", "contact_access": "No public affiliate email appears on the collabs page; contact runs through the program application itself.", "opportunity_availability": "Open application on the brand''s own collabs page with a simple stated requirement (post twice a month).", "credibility": "Established Australian haircare brand with published rates and payout cadence on its own store."}'::jsonb);
