  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 16, 12, 9, 4, '{"niche_fit": "Press-on nails and magnetic lashes are among the highest-converting TikTok Shop beauty demos \u2014 application videos are the sales pitch.", "ugc_evidence": "The brand runs its whole growth engine through TikTok Shop creators: published commission tiers, GMV contests with large prizes and a verified-creator Discord community.", "compensation": "Published on the brand''s own terms page: 15% cash commission on open collaborations, rising to 23% for target collaborations \u2014 paid by TikTok Shop.", "contact_access": "A dedicated TikTok Shop affiliate email (tiktokshop@glamnetic.com) is published on the brand''s own site.", "opportunity_availability": "Open collaboration on TikTok Shop is available to approved TikTok Shop affiliates without an invite; higher tiers are invite/verification based.", "credibility": "Established DTC beauty brand with detailed, legally drafted TikTok Shop program terms published on its own store."}'::jsonb);
