  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.lovingtan.com/pages/affiliates', 'official_site', 'affiliate', 'Loving Tan''s own affiliates page offers ''up to 15% commission on each sale (excluding gift cards)'' with a 30-day cookie window, bonuses for high-performing affiliates and free samples for select partners. ''Up to 15%'' is a ceiling, not a published base rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/loving-tan/', 'listing', 'compensation', 'Third-party listings conflict on the actual rate: LinkClicky lists 10% per sale via Impact, FlexOffers lists 4–8% for the US program, and a Katalys-based review cites a 3% default. Because the brand''s own page publishes only a 15% ceiling and the listings disagree, commission_rate is recorded as null with the conflict documented.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 10, 7, 8, 4, '{"niche_fit": "Self-tan application and results content is a staple beauty-UGC format with strong before/after appeal.", "ugc_evidence": "The brand''s own affiliates page recruits influencers directly and offers samples to select partners; the brand was built on influencer marketing.", "compensation": "The brand publishes only an ''up to 15%'' ceiling and third-party listings conflict (3% / 4\u20138% / 10%), so no base rate can be honestly recorded.", "contact_access": "No public affiliate email appears on the fetched program page; sign-up runs through the page''s application link.", "opportunity_availability": "Open application from the brand''s own affiliates page.", "credibility": "Long-running Australian tanning brand (since 2010) with a US storefront and published program outline on its own site."}'::jsonb);
