  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partners.foreo.com/how-to-choose-the-best-affiliate-programs-and-networks-in-the-uk-with-top-picks/', 'official_site', 'affiliate', 'FOREO''s own partner blog states its program pays 5–15% per sale through Awin, CJ Affiliate and Rakuten with 30–60 day cookies and no minimum follower requirements. The 5% floor conflicts with the affiliate page''s 2% floor, so no single rate is recorded; the published range is 2–15%.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 9, 8, 8, 5, '{"niche_fit": "Skincare devices are premium demo products \u2014 cleansing, masking and microcurrent routines are natural short-form content with high basket values.", "ugc_evidence": "The brand recruits bloggers and creators on its own affiliate page and offers a dedicated account manager, though its program is publisher-led rather than creator-native.", "compensation": "Only a wide 2\u201315% range is published and the brand''s own pages conflict on the floor (2% vs 5%), so no base rate can be honestly recorded.", "contact_access": "No public affiliate email appears on the fetched pages; support runs through the network and a dedicated account manager after joining.", "opportunity_availability": "Open registration via Rakuten/HasOffers, and the brand states there are no minimum follower requirements.", "credibility": "Global beauty-tech leader with worldwide retail distribution and long-running network programs on Rakuten, Awin and CJ."}'::jsonb);
