  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/vacation-inc', 'listing', 'ugc_collab', 'Rateful''s TikTok Shop analysis (third-party estimates, not brand-published figures) reports that roughly 70% of Vacation''s TikTok Shop sales in the 30 days to Nov 6, 2026 came through affiliate creators'' videos and LIVEs — evidence of a creator-driven sales model, though no absolute creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 8, 7, 8, 4, '{"niche_fit": "Sunscreen with a distinctive scent and retro branding gives creators an easy sensory hook; SPF routines and travel content are steady short-form categories.", "ugc_evidence": "Third-party TikTok Shop data attributes roughly 70% of the brand''s recent TikTok Shop sales to affiliate creators \u2014 the brand sells through creators by design.", "compensation": "No commission rate is published on the network profile or any fetched page, so compensation cannot be graded beyond program existence.", "contact_access": "No public affiliate contact appears on the fetched profile; contact runs through Awin.", "opportunity_availability": "Open to apply through Awin; the brand also sells through TikTok Shop''s affiliate system.", "credibility": "Well-known, retail-distributed sunscreen brand with an irreverent but established brand identity and a live program on a major network."}'::jsonb);
