  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.afflemi.com/affiliate-programs/p/asos', 'affiliate_network', 'affiliate', 'Afflemi''s ASOS program page (fetched) states the program runs on Awin with a 30-day cookie and tiered commission: up to 6% on orders from new customers, 3% from existing customers and 1% on sale items, with reviewed applications and payouts on Awin''s monthly schedule.', 'publicly_reported', now());
