  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 14, 8, 8, 8, 5, '{"niche_fit": "One of the largest online fashion catalogues in the world (850+ brands plus own labels) \u2014 outfit, haul and trend content fits naturally.", "ugc_evidence": "ASOS runs a reviewed publisher program with feeds, banners and deep links and is a staple of fashion creator content, though it publishes no creator-specific program page.", "compensation": "Tiered rates are reported (up to 6% new customers / 3% existing / 1% sale items on Awin), but published figures conflict across sources (roughly 1% to 10%), so the rate is honestly left null; no earnings cap is stated anywhere fetched.", "contact_access": "No public partnerships email or brand application page was verified; access is through network publisher accounts only.", "opportunity_availability": "Open application through Awin (and Rakuten in the US) with manual review for fashion-relevant sites and channels.", "credibility": "FTSE-listed global fashion retailer founded in 2000 with a long-running affiliate program across major networks."}'::jsonb);
