  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.stevemadden.com/pages/sm-ambassadors-terms-and-conditions?srsltid=AfmBOopBBnDZhPwTOTrdAik6ZcY0bTRx-KHyDFQutJ8cPlmEtw0iXnBu', 'official_site', 'affiliate', 'Steve Madden''s official SM Ambassadors terms (fetched in full) run an own-brand affiliate program for social creators: apply through the Madden Site, post wearing the product tagging @SteveMadden with #SteveMaddenPartner, and earn commission on Qualified Purchases from new referred customers.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.stevemadden.com/pages/sm-ambassadors-terms-and-conditions?srsltid=AfmBOopBBnDZhPwTOTrdAik6ZcY0bTRx-KHyDFQutJ8cPlmEtw0iXnBu', 'official_site', 'compensation', 'Section 7 of the official terms sets the cash rate: affiliates who select PayPal payment earn 5% for each Qualified Purchase, paid 60 days after the order date; the alternative payment method is a discount code worth 10% of the Qualified Purchase for the affiliate''s own use on the Madden Site. The 5% cash rate is recorded; the 10% code is store credit, not cash.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/steve-madden/', 'listing', 'compensation', 'Lasso lists a separate Steve Madden network listing at 6.4% per sale with a 7-day cookie, and affiliateprogramsguru reports 5% through Rakuten with a 30-day cookie — secondary routes that differ from the own-program terms recorded here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 10, 11, 7, 5, '{"niche_fit": "Trend footwear and bags are a staple of fashion creator content \u2014 GRWM, styling and shoe-haul formats fit the catalogue directly.", "ugc_evidence": "The SM Ambassadors program is built specifically for social media creators, with defined posting rules, a required partner hashtag and gifted product at the brand''s discretion.", "compensation": "5% cash per qualified purchase via PayPal under the brand''s own published terms (a 10%-of-purchase discount code is the non-cash alternative); third-party network listings cite 5-6.4%. No earnings cap is stated in the fetched terms, so the cap is honestly unknown.", "contact_access": "Full program terms and the application route are published on the brand''s own site, though no partnerships email is published.", "opportunity_availability": "Application is open through the Madden Site but acceptance is at the brand''s sole discretion and limited to US residents aged 18+.", "credibility": "Publicly traded footwear company (Steven Madden, Ltd.) founded in 1990 with global retail distribution."}'::jsonb);
