  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://feelingirl.com/pages/afflite?ref=fg', 'official_site', 'affiliate', 'FeelinGirl''s own ambassador page (fetched in full) states: ''We offer 10%-15% commission on the goaffpro affiliate platform'', with joining handled through its GoAffPro portal (feelingirl.goaffpro.com); ambassadors get free samples, custom referral links, exclusive coupons and brand features.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://feelingirl.com/pages/afflite?ref=fg', 'official_site', 'contact', 'The same official page publishes info@feelingirl.com for general contact and press@feelingirl.com for media and press inquiries, and its FAQ says anyone over 18 who is active on social media can become an ambassador (a related page mentions 10k followers for the ambassador tier).', 'verified', now());
