  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 14, 13, 9, 3, '{"niche_fit": "Shapewear and bodysuits are a proven TikTok fashion niche (try-on, before/after and review formats), though narrower than general apparel.", "ugc_evidence": "A dedicated ambassador program with brand missions, product samples, official features of creator photos on the brand''s own page and exclusive creator channels.", "compensation": "10-15% commission published on the brand''s own ambassador page \u2014 a strong rate for apparel; the 10% floor is recorded. No earnings cap is stated on the fetched page, so the cap is honestly unknown.", "contact_access": "Self-serve join through the brand''s GoAffPro portal plus two published emails (general and press) on the program page itself.", "opportunity_availability": "Open today; the brand''s FAQ says anyone 18+ active on social media can become an ambassador, with a 10k-follower mention for the ambassador tier on a related page.", "credibility": "Smaller DTC shapewear label without the track record of the larger retailers in this group; a mirror storefront (feelingirlbodysuit.com) also operates."}'::jsonb);
