  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.commissionfactory.com/advertiser-directory/chicme-affiliate-program/49287', 'affiliate_network', 'affiliate', 'Commission Factory''s own advertiser page for ChicMe (fetched) states a default commission of 12% per sale with a 14-day cookie, partner-specific rates possible, and partnership enquiries handled through Commission Factory.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/chicme/', 'listing', 'compensation', 'Lasso lists ChicMe at ''8% and 10.4% per sale'' with a 14-day cookie, which differs from Commission Factory''s published 12% default; the network''s own current page is weighted and the difference documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://revieweek.com/review/chicme/', 'listing', 'ugc_collab', 'Revieweek''s ChicMe review describes a blogger program for creators with 500+ followers or unique visitors offering free product plus a fixed reward for tagged posts, alongside the affiliate program — a gifting-plus-fee route separate from the commission program recorded here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 10, 13, 8, 8, 3, '{"niche_fit": "Budget women''s fast fashion (dresses, swim, occasionwear) maps directly onto haul and try-on creator content.", "ugc_evidence": "A standard network affiliate program plus a reported blogger program (free product and a fixed fee for 500+ follower creators); no dedicated creator portal or ambassador scheme was verified.", "compensation": "12% default commission per the network''s own advertiser page \u2014 high for fast fashion \u2014 though a third-party listing cites 8-10.4% instead. No earnings cap is stated in any fetched source, so the cap is honestly unknown.", "contact_access": "No public brand email was verified; partnership contact runs through the Commission Factory dashboard only.", "opportunity_availability": "Open application through Commission Factory today; a FlexOffers listing for the same brand is marked not currently offered, so Commission Factory is the live route.", "credibility": "Budget cross-border fast-fashion retailer operating since 2015 with mixed consumer reviews; smaller and less established than the major retailers in this group."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Booking.com', 'https://www.booking.com', 'One of the world''s largest online travel agencies, offering 29M+ accommodation listings plus flights, car rental, attractions and airport taxis in 45 languages through booking.com.', 'Netherlands', 'published') returning id into bid;
