  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.cj.com/en-gb/publisher/partners/booking.com.', 'https://www.cj.com/en-gb/publisher/partners/booking.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Booking.com Affiliate Programme (via CJ)', 'https://www.cj.com/en-gb/publisher/partners/booking.com', 'https://www.cj.com/en-gb/publisher/partners/booking.com', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cj.com/en-gb/publisher/partners/booking.com', 'affiliate_network', 'affiliate', 'CJ''s own Booking.com partner page (fetched in full) states the programme is session-based and pays, on completed travel: 4% for accommodation stays, 6% for car rentals, 4% for attractions, £2/€2 per flight and 4% for taxi rides, with rates that may vary by performance and volume; new applicants register through CJ by region.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cj.com/en-gb/publisher/partners/booking.com', 'affiliate_network', 'ugc_collab', 'The same CJ page says the programme ''welcomes travel bloggers, influencers, and website owners'' but ''will not accept publishers to the programme with social media only profiles'' — creators need an active website or blog as well.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/booking-com-affiliate-program/', 'listing', 'compensation', 'AffiliateProgramsGuru describes the same program as paying 25-40% of Booking.com''s own commission revenue by monthly volume (roughly 4-8% of booking value), an alternative framing of the CJ-stated rates; the CJ page''s direct percentages of booking value are recorded, with this basis difference documented.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 12, 9, 9, 7, 5, '{"niche_fit": "The default hotel-booking link for travel content worldwide \u2014 29M+ listings, flights, cars and attractions in one program.", "ugc_evidence": "CJ''s page explicitly welcomes travel bloggers and influencers, but there is no creator-specific tier and social-only profiles are refused, which limits pure social creators.", "compensation": "4% of booking value on completed stays to start (6% cars, 4% attractions/taxis, flat \u00a32/\u20ac2 flights) per CJ''s own page; session-based tracking \u2014 the booking must complete in the same browser session \u2014 is a real earnings constraint. No earnings cap is stated, so the cap is honestly unknown.", "contact_access": "Application and support run through CJ''s publisher platform; no public brand partnerships email was verified.", "opportunity_availability": "Open via CJ by region today, but an active website or blog is required \u2014 social-media-only creators are not accepted.", "credibility": "One of the world''s largest travel companies (Booking Holdings), with 4.5 billion guest arrivals since 2021 per CJ''s page."}'::jsonb);
