  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/p/expedia-travel-creator-affiliate', 'affiliate_network', 'affiliate', 'WhichProgram''s Expedia Travel Creator entry (fetched) records the program on CJ Affiliate with a 7-day cookie and application required, quoting the network''s stated structure: ''4% hotels & activities; 2% vacation rentals & packages; 1.5% cars.''', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/expedia-affiliate-program/', 'listing', 'compensation', 'AffiliateProgramsGuru''s Expedia entry (verified March 2026) corroborates the same tiers — 4% hotels and activities, 2% vacation rentals and packages, 1.5% cars, flights not commissionable, 7-day cookie — and lists CJ Affiliate, Awin and Expedia''s direct Affiliate Hub as join routes.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/p/expedia-travel-creator-affiliate', 'affiliate_network', 'compensation', 'WhichProgram''s own directory header records a conflicting ''$1.50 to $4.00 per action'' CPA figure for the same CJ program, which does not match the percentage structure it quotes from the network; the network-stated percentage tiers are recorded and the flat figure documented as a conflict.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 12, 9, 9, 8, 5, '{"niche_fit": "Full-service travel booking (hotels, rentals, packages, cars, activities) fits virtually all travel content verticals.", "ugc_evidence": "The program is now branded the Travel Creator Program and reviews influencer applicants, but remains a general publisher program rather than a creator-first scheme.", "compensation": "4% on hotels and activities is the headline network-stated tier (2% rentals/packages, 1.5% cars, 7-day cookie); one directory''s flat $1.50-$4.00 per-action figure conflicts and is documented. No earnings cap is stated in any fetched source, so the cap is honestly unknown.", "contact_access": "Joinable through CJ or Expedia Group''s own Affiliate Hub; no public partnerships email was verified.", "opportunity_availability": "Open application via CJ/Awin or the direct hub, with a site-quality review; influencer applicants are reported to need at least 1,000 followers and active travel content.", "credibility": "Expedia Group is one of the world''s largest travel companies, operating Expedia, Hotels.com and Vrbo."}'::jsonb);
