  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 10, 13, 8, 5, '{"niche_fit": "Luggage is a narrower slice of travel, but packing, gear-review and travel-hack content makes it a natural creator fit.", "ugc_evidence": "The Awin profile explicitly offers custom rates for top publishers and influencers and seasonal creative support, though there is no standalone creator program.", "compensation": "5% base commission confirmed in both the Awin profile and the program''s own Awin terms, with custom higher rates for top performers; no earnings cap is stated, so the cap is honestly unknown.", "contact_access": "The affiliate team''s email (affiliates@delsey.com) is published directly on the Awin merchant profile \u2014 unusually accessible for a heritage brand.", "opportunity_availability": "Open application through Awin today with published terms, a $50 payout threshold and monthly payments.", "credibility": "French luggage house with 75+ years of heritage and global retail distribution, per its Awin profile."}'::jsonb);
