  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 17, 8, 7, 3, '{"compensation": "Flat $40 bounty per collar purchase (recorded as a flat bounty, so commission_rate is null), and the brand''s own page explicitly states there is no cap on earnings \u2014 a verified uncapped program. Quarterly payouts after a 30-day return window are slower than monthly networks.", "contact_access": "Open application on the brand''s own affiliate page; no direct email published.", "credibility": "Smaller company (founded 2012, Israel HQ with a US office) and the program page sits on a content subdomain, so it scores below large established brands despite the verified terms.", "niche_fit": "Pet health-tech is a compelling niche for dog creators \u2014 health alerts and activity data make strong story-driven content.", "opportunity_availability": "Program live with fast approval promised on the brand''s page.", "ugc_evidence": "The brand runs an open affiliate program aimed at anyone who shares with pet owners; no large creator roster is published."}'::jsonb);
