  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Dovetale', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://k9ballistics.com/pages/collab.', 'https://k9ballistics.com/pages/collab', 'needs_review', now());
