  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://k9ballistics.com/pages/collab', 'brand_site', 'creator_program_page', 'K9 Ballistics'' own Collabs page (fetched) invites creators into its Affiliate Program with free products, commissions on sales and campaign partnerships; listed partnership types include affiliate marketing, gifting, campaigns, content creation and usage rights. The page is powered by Dovetale. No commission rate is published on the page.', 'verified', now());
