  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 11, 9, 6, 4, '{"compensation": "The brand publishes no rate; a third-party directory reports 10% per sale, so the rate is recorded as null. No earnings cap is stated anywhere found, so the cap is unknown, not uncapped.", "contact_access": "Direct application through the brand''s own Collabs page (Dovetale-powered).", "credibility": "Established premium pet brand with a long-running DTC store and a 120-day chew-proof guarantee.", "niche_fit": "Indestructible dog beds are a proven demo format (chew tests, durability challenges) for pet creators.", "opportunity_availability": "Collabs page live and openly inviting applications.", "ugc_evidence": "The brand''s own Collabs page recruits creators for affiliate commissions, gifting, campaigns and content creation \u2014 direct evidence of an active creator program."}'::jsonb);
